 * @param {import('./types.js').Specificity} a
 * @param {import('./types.js').Specificity} b
 * @returns {number}
 */
export const compareSpecificity = (a, b) => {
  for (let i = 0; i < 4; i += 1) {
    if (a[i] < b[i]) {
      return -1;
    } else if (a[i] > b[i]) {
      return 1;
    }
  }

  return 0;
};

