};

/**
 * @param {import('./types.js').Stylesheet} stylesheet
 * @param {import('./types.js').XastElement} node
 * @returns {import('./types.js').ComputedStyles}
 */
export const computeStyle = (stylesheet, node) => {
  const { parents } = stylesheet;
