};

export type BuiltinPluginOrPreset<Name extends string, Params> = BuiltinPlugin<
  Name,
  Params
> &
  (PresetProperties<true> | Partial<PresetProperties<false>>);

export type XastDoctype = {
  type: 'doctype';
