};

export type VisitorNode<Node> = {
  enter?: (node: Node, parentNode: XastParent) => void | symbol;
  exit?: (node: Node, parentNode: XastParent) => void;
};

export type VisitorRoot = {
  enter?: (node: XastRoot, parentNode: null) => void;
