const parseStyleDeclarations = (css, cache) => {
  const cached = cache?.get(css);
  if (cached != null) {
    return cached;
  }
  /** @type {import('./types.js').StylesheetDeclaration[]} */
  const declarations = [];
  const ast = csstree.parse(css, {
    context: 'declarationList',
    parseValue: false,
